CREATE TABLE IF NOT EXISTS accounts (vpa VARCHAR(255) NOT NULL PRIMARY KEY, holder_name VARCHAR(255) NOT NULL, balance DECIMAL(19,2) NOT NULL, pin_hash VARCHAR(64), version BIGINT);
CREATE TABLE IF NOT EXISTS transactions (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, packet_hash VARCHAR(64) NOT NULL UNIQUE, sender_vpa VARCHAR(255) NOT NULL, receiver_vpa VARCHAR(255) NOT NULL, amount DECIMAL(19,2) NOT NULL, signed_at DATETIME(6) NOT NULL, settled_at DATETIME(6) NOT NULL, bridge_node_id VARCHAR(255) NOT NULL, hop_count INTEGER NOT NULL, status VARCHAR(255) NOT NULL);
